def create_copies_and_relink_loans(apps, schema_editor):
    database = schema_editor.connection.alias
    Book = apps.get_model('core', 'Book')
    BookCopy = apps.get_model('core', 'BookCopy')
    Loan = apps.get_model('core', 'Loan')
    categories = ['paperback', 'hardcover', 'digital']
    barcode_number = 1
    original_loans = list(
        Loan.objects.using(database)
        .order_by('pk')
        .values_list('pk', 'book_id', 'return_date')
    )
    loans_by_book = {}
    for loan_id, book_id, return_date in original_loans:
        loans_by_book.setdefault(book_id, []).append((loan_id, return_date))

    for book in Book.objects.using(database).order_by('pk'):
        BookCopy.objects.using(database).create(
            book_id=book.pk,
            barcode=f'BC{barcode_number:013d}',
            category=categories[(barcode_number - 1) % len(categories)],
            status='in_stock',
        )
        barcode_number += 1

        for loan_id, return_date in loans_by_book.get(book.pk, []):
            copy = BookCopy.objects.using(database).create(
                book_id=book.pk,
                barcode=f'BC{barcode_number:013d}',
                category=categories[(barcode_number - 1) % len(categories)],
                status='loaned' if return_date is None else 'in_stock',
            )
            barcode_number += 1
            Loan.objects.using(database).filter(pk=loan_id).update(book_id=copy.pk)


def restore_book_links(apps, schema_editor):
    database = schema_editor.connection.alias
    BookCopy = apps.get_model('core', 'BookCopy')
    Loan = apps.get_model('core', 'Loan')

    for loan in Loan.objects.using(database).order_by('pk'):
        loan.book_id = BookCopy.objects.using(database).get(pk=loan.book_id).book_id
        loan.save(using=database, update_fields=['book'])


